[Part III · Computer · Q.85]
What will be the output of the following C++ code?
#include <iostream.h>
using namespace std;
void square(int *x, int *y)
{
    *x = (*x) * --(*y);
}
int main()
{
    int number = 30;
    square(&number, &number);
    cout << number;
    return 0;
}
